// 2026-05-25 OTA-044 — chained narrative helper. Called at the end of
// every contract turn-in (hunt / mystery / storyline / faction_quest)
// to plant a one-line teaser for the NEXT contract from the same
// faction. If no follow-up is available, falls through to a generic
// "your reputation precedes you" Arbiter beat. Goal: every finish
// frays at the edges so the player goes to bed thinking about what
// they were about to start.
type ContractKind = 'hunt' | 'mystery' | 'storyline' | 'faction_quest';
/** OTA-617 — BUILDING-LEVEL turn-in proximity. A faction quest counts as "in
 *  person" (full reward + auto-submit on arrival) when you're EITHER in a scene
 *  with a same-faction vendor / mission board, OR anywhere inside that faction's
 *  home OUTPOST building. The player asked not to require the exact board room —
 *  walking into the building is enough. Couriering from afar (the Contracts
 *  COMPLETE button while NOT in the building) still pays HALF, so arb171's
 *  "full reward from anywhere" exploit stays closed. */
function atFactionTurnInBuilding(get: () => GameStore, factionId: string): boolean {
  const player = get().player;
  const scene = get().currentScene;
  if (!player) return false;
  if (scene?.vendor?.faction === factionId || scene?.missionBoard?.faction === factionId) return true;
  try {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { startingLocationForFaction } = require('../engine/character');
    return isHubLocation(player.currentLocationId)
      && startingLocationForFaction(factionId) === player.currentLocationId;
  } catch {
    return false;
  }
}
/** arb171 — on arrival at a scene where a same-faction vendor or mission board is
 *  present, auto-turn-in every active faction quest whose WORK is done (staged →
 *  all stages; fetch → items in hand), at FULL reward, and surface a completion
 *  popup. This is the "submit on arrival at the routed spot" the player asked for
 *  — OTA correction: the Contracts COMPLETE button is NOT a remote half option
 *  anymore; it delegates to the same face-to-face typed turn-ins (see
 *  completeContractFromUI — "in person or not at all"). */
function autoSubmitReadyFactionQuests(
  get: () => GameStore,
  set: (fn: (s: GameStore) => Partial<GameStore>) => void,
): void {
  const player = get().player;
  const scene = get().currentScene;
  if (!player || !scene) return;
  const countItem = (name: string) =>
    (player.inventory ?? [])
      .filter((i) => i.name.toLowerCase() === name.toLowerCase())
      .reduce((n, i) => n + (i.quantity ?? 1), 0);
  // OTA-617 — fire for every ready faction quest whose turn-in is reachable from
  // HERE (a same-faction agent/board in scene, OR you're inside that faction's
  // home building). No longer requires the exact board room.
  const ready = (player.activeFactionQuests ?? [])
    .map((rec) => ({ rec, def: findFactionQuestById(rec.id) }))
    .filter(({ rec, def }) => !!def && factionQuestReady(def, rec.stage, countItem) && atFactionTurnInBuilding(get, def.factionId));
  if (ready.length === 0) return;
  const lines: string[] = [];
  const rewards: string[] = [];
  for (const { def } of ready) {
    if (!def) continue;
    // In-person turn-in → FULL reward, atomic removal, fetch consume — all via
    // the canonical path so there's a single source of truth.
    get().turnInFactionQuest(def.id, false);
    const stillActive = (get().player?.activeFactionQuestIds ?? []).includes(def.id);
    if (!stillActive) {
      lines.push(`✓ ${def.title}`);
      rewards.push(`+${def.reward.tc} TC${def.reward.rep > 0 ? ` · +${def.reward.rep} rep` : ''}`);
    }
  }
  if (lines.length > 0) {
    set(() => ({
      pendingWhisperComplete: {
        title: lines.length === 1 ? 'Contract Turned In' : 'Contracts Turned In',
        lines,
        rewards,
      },
    }));
  }
}

function plantNextContractHint(
  get: () => GameStore,
  factionId: string | null,
  kind: ContractKind,
): void {
  const player = get().player;
  if (!player) return;
  let nextTitle: string | undefined;
  if (factionId) {
    const rep = getStanding(player.factionStanding, factionId);
    if (kind === 'hunt') {
      const pool = availableHunts(
        factionId,
        rep,
        (player.activeHunts ?? []).map((h) => h.id),
        player.completedHuntIds ?? [],
      );
      nextTitle = pool[0]?.title;
    } else if (kind === 'mystery') {
      const pool = availableMysteries(
        factionId,
        rep,
        (player.activeMysteries ?? []).map((m) => m.id),
        player.completedMysteryIds ?? [],
      );
      nextTitle = pool[0]?.title;
    } else if (kind === 'storyline') {
      const pool = availableStorylines(
        factionId,
        rep,
        (player.activeStorylines ?? []).map((s) => s.id),
        player.completedStorylineIds ?? [],
      );
      nextTitle = pool[0]?.title;
    } else {
      const pool = availableFactionQuests(
        factionId,
        rep,
        player.activeFactionQuestIds ?? [],
        player.completedFactionQuestIds ?? [],
      );
      nextTitle = pool[0]?.title;
    }
  }
  if (nextTitle) {
    const kindLabel = kind === 'hunt' ? 'hunt'
      : kind === 'mystery' ? 'mystery'
      : kind === 'storyline' ? 'chapter'
      : 'contract';
    get().appendLog(
      'arbiter',
      `Before you go, the agent slides a second leaf across the table. "Something heavier when you're ready — the ${kindLabel} '${nextTitle}'."`,
    );
  } else {
    get().appendLog(
      'arbiter',
      `Word will travel that you finished this clean. The next thread will find you.`,
    );
  }
}

